class {{class_name}}:
    def __init__(self, size=1024, hashes=4):
        self.size = size
        self.hashes = hashes
        self.bits = [0]*size
    def _idx(self, item, i):
        h = hashlib.md5(f'{i}:{item}'.encode()).hexdigest()
        return int(h, 16) % self.size
    def add(self, item):
        for i in range(self.hashes):
            self.bits[self._idx(item, i)] = 1
    def __contains__(self, item):
